function defaults(t){const out={};for(const [k,[,type,,value]]of Object.entries(models[t].fields)){if(type==='checkbox')out[k]=false;else if(type==='number')out[k]=k==='credits'?4:k==='duration_minutes'?60:k==='capacity'?1:0;else if(type==='select')out[k]=value?.split('|')[0]||'';else if(value)out[k]=value;}if(t==='package_templates')out.active=true;return out;}
