 const [petId,setPetId]=useState(initial?.pet_id||''),[serviceId,setServiceId]=useState(initial?.service_id||''),[extras,setExtras]=useState([]),[query,setQuery]=useState('');const pet=lists.pets.find(p=>p.id===petId),service=lists.services.find(s=>s.id===serviceId);const packages=lists.packages.filter(p=>p.pet_id===petId&&p.service_id===serviceId&&p.balance>0&&new Date(p.expires_at)>new Date());
