 return <><label><span>Localizar pet pelo nome ou tutor</span><input placeholder="Buscar pet…" value={query} onChange={e=>setQuery(e.target.value)}/></label><div className="pet-picker">{lists.pets.filter(p=>`${p.name} ${lists.tutors.find(t=>t.id===p.tutor_id)?.name} ${short(p.id)}`.toLowerCase().includes(query.toLowerCase())).slice(0,20).map(p=><button type="button" className={petId===p.id?'selected':''} key={p.id} onClick={()=>setPetId(p.id)}><Avatar pet={p}/><span><strong>{p.name}</strong><small>{lists.tutors.find(t=>t.id===p.tutor_id)?.name} · {short(p.id)}</small></span>{petId===p.id&&<Check size={16}/>}</button>)}</div>{pet&&<p className="notice">{pet.name} · {pet.breed||pet.species} · {pet.size}{pet.allergies&&<><br/>Cuidados: {pet.allergies}</>}{pet.diet&&<><br/>Alimentação: {pet.diet}</>}{lists.health.filter(h=>h.pet_id===petId&&(h.proof_status==='pendente'||h.due_date<dayOf(new Date()))).map(h=><span className="danger block" key={h.id}>{h.name} · próxima {date(h.due_date)} · {h.proof_status}</span>)}</p>}<label><span>Serviço *</span><select value={serviceId} onChange={e=>setServiceId(e.target.value)}><option value="">Selecione</option>{lists.services.filter(s=>s.active&&s.kind!=='extra'&&(!kind||s.kind===kind)).map(s=><option key={s.id} value={s.id}>{s.name} · {kindLabels[s.kind]}</option>)}</select></label><div className="notice">{service?.price_cents!==undefined&&service.kind!=='boarding'?`Avulso: ${money(service.price_cents)} · `:''}Selecione um pacote para usar créditos. Hospedagem segue as regras de duração e temporada configuradas.</div><Form key={petId+serviceId} fields={fields} lists={{...lists,packages}} initial={{user_id:initial?.user_id||'',package_id:'',discount_cents:0,notes:initial?.notes||''}} save={async v=>{if(!petId||!serviceId)throw Error('Selecione pet e serviço.');await save({...v,pet_id:petId,service_id:serviceId,extras,start_at:new Date(v.start_at+'-03:00').toISOString(),end_at:new Date(v.end_at+'-03:00').toISOString()});}} submit="Salvar agendamento"><fieldset><legend>Adicionais solicitados</legend><div className="checks">{lists.services.filter(s=>s.active&&s.kind==='extra').map(s=><label key={s.id}><input type="checkbox" checked={extras.includes(s.id)} onChange={e=>setExtras(e.target.checked?[...extras,s.id]:extras.filter(id=>id!==s.id))}/>{s.name}{s.price_cents!==undefined&&' · '+money(s.price_cents)}</label>)}</div></fieldset><p className="notice">Agendar não conclui o atendimento. O pacote só será consumido após a conclusão válida. Adicionais serão cobrados à parte.</p></Form></>;
