function UserForm({record:r,lists,save}){
 const initial=r?{...r,permissions:JSON.parse(r.permissions),commission_services:JSON.parse(r.commission_services)}:{name:'',email:'',role:'operation',active:true,salary_cents:0,commission_kind:'none',commission_value:0,commission_basis:'charged',commission_services:[],permissions:{}};
 return <Form fields={{name:['Nome','text',true],email:['E-mail da conta ChatGPT','email',true],role:['Perfil','select',true,'management|operation|technical'],active:['Acesso ativo','checkbox'],salary_cents:['Remuneração fixa (R$)','money'],commission_kind:['Comissão','select',true,'none|fixed|percent'],commission_value:['Valor: centavos para fixa / 100 = 1% para percentual','number'],commission_basis:['Base de cálculo','select',true,'charged|allocated']}} initial={initial} lists={lists} save={save}>{(v,setV)=><><fieldset><legend>Serviços elegíveis para comissão</legend><div className="checks">{[...lists.services.filter(s=>s.kind!=='extra'),{id:'products',name:'Vendas de produtos'}].map(s=><label key={s.id}><input type="checkbox" checked={v.commission_services.includes(s.id)} onChange={e=>setV({...v,commission_services:e.target.checked?[...v.commission_services,s.id]:v.commission_services.filter(id=>id!==s.id)})}/>{s.name}</label>)}</div></fieldset><p className="notice">Comissões são apuradas na conclusão/postagem. Pagamento é registrado no financeiro. Recuperação de acesso pela conta ChatGPT.</p><details><summary>Permissões por área e ação</summary>{Object.entries(permissionNames).map(([domain,label])=><div className="permission-row" key={domain}><strong>{label}</strong>{['read','create','edit','cancel','export','approve'].map(a=><label key={a}><small>{{read:'Ler',create:'Criar',edit:'Editar',cancel:'Cancelar',export:'Exportar',approve:'Aprovar'}[a]}</small><select value={v.permissions[domain]?.[a]===undefined?'':String(v.permissions[domain][a])} onChange={e=>{const p=structuredClone(v.permissions);p[domain]||={};if(e.target.value==='')delete p[domain][a];else p[domain][a]=e.target.value==='true';setV({...v,permissions:p});}}><option value="">Perfil</option><option value="true">Sim</option><option value="false">Não</option></select></label>)}</div>)}</details></>}</Form>;
}
function UploadForm({modal,save}){
 const [file,setFile]=useState(null),[kind,setKind]=useState(modal.brand?'brand':'document'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const f=new FormData();f.set('file',file);f.set('kind',kind);if(modal.pet_id)f.set('pet_id',modal.pet_id);if(modal.health_id)f.set('health_id',modal.health_id);await save(f);}catch(e){setError(e.message);}finally{setBusy(false);}}}>{!modal.brand&&<label><span>Tipo</span><select value={kind} onChange={e=>setKind(e.target.value)}><option value="document">Documento ou comprovante</option><option value="photo">Foto principal</option><option value="activity">Foto de atividade</option></select></label>}<label className="upload-area"><Upload size={29}/><strong>Escolha um arquivo</strong><small>JPEG, PNG, WebP{kind==='document'?' ou PDF':''} · até 5 MB</small><input type="file" required accept={kind==='document'?'image/jpeg,image/png,image/webp,application/pdf':'image/jpeg,image/png,image/webp'} onChange={e=>setFile(e.target.files[0])}/></label>{error&&<p className="error">{error}</p>}<div className="form-footer"><small>Arquivo privado da empresa.</small><button disabled={!file||busy} className="button">{busy?'Enviando…':'Salvar arquivo'}</button></div></form>;
}
